styles.css:
/* SensiHome PAW: vlastní styly (Vzhled > Editor > Styly > Další CSS) */
body { --shp-accent:#1A9AA8; --shp-accent-dark:#1F8A96; --shp-tint:#E7F5F6; --shp-ink:#22343C; --shp-text:#4A5B63; --shp-muted:#8A9AA0; --shp-bg:#FBF8F3; --shp-sand:#F6F1EA; --shp-line:#EEE7DD; -webkit-font-smoothing:antialiased; }
:where(.wp-site-blocks) > * { margin-block-start:0; }
.wp-site-blocks { padding-top:0; padding-bottom:0; }
main.wp-block-group { margin-top:0 !important; }
p { color: var(--shp-text); }
h1,h2,h3,h4 { text-wrap: balance; }
p { text-wrap: pretty; }

/* ručně psaný akcent */
.shp-hand { font-family: var(--wp--preset--font-family--caveat) !important; font-weight:600; color: var(--shp-accent) !important; font-size: 32px !important; line-height:1 !important; margin-bottom: 6px !important; }
.shp-lead { font-size: 19px; line-height:1.55; max-width: 520px; }
.shp-intro { font-size: 18px; max-width: 680px; }
.shp-note { font-size: 14px; color: var(--shp-muted) !important; margin: 0 !important; }
.shp-center { justify-content: center; }

/* tlačítka */
.wp-element-button, .wp-block-button__link { min-height: 52px; display:inline-flex; align-items:center; justify-content:center; box-shadow: 0 10px 24px rgba(26,154,168,.28); transition: background .15s, filter .15s; }
.wp-block-button.is-style-outline > .wp-block-button__link { background: transparent !important; color: var(--shp-ink) !important; border: 0 !important; box-shadow: inset 0 0 0 2px var(--shp-accent) !important; }
.wp-block-button.is-style-outline > .wp-block-button__link:hover { background: var(--shp-tint) !important; }
.wp-block-buttons { gap: 14px; margin-top: 10px; }

/* fotky */
.shp-photo img { border-radius: 28px; width:100%; height:100%; object-fit: cover; box-shadow: 0 18px 40px rgba(34,52,60,.12); }
.shp-photo-hero img { aspect-ratio: 5 / 4; }
.shp-qr img { width: 180px; border-radius: 12px; border: 1px solid var(--shp-line); }

/* sekce */
.shp-section, .shp-hero, .shp-pagehead { padding: 72px var(--wp--style--root--padding-right, 24px) !important; }
.shp-section { margin-top: 0 !important; margin-bottom: 0 !important; }
.shp-white { background:#fff; border-top:1px solid var(--shp-line); border-bottom:1px solid var(--shp-line); }
.shp-hero { padding-top: 56px !important; padding-bottom: 64px !important; }
.shp-hero h1 { margin-bottom: 4px; }
.shp-hero .shp-hand { font-size: 38px !important; }
.shp-pagehead { padding-bottom: 24px !important; }
.shp-pagehead .shp-lead { max-width: 720px; }
.wp-block-columns { gap: 56px; }

/* kategorie */
.shp-catbar { background:#fff; border-top:1px solid var(--shp-line); border-bottom:1px solid var(--shp-line); margin-top:0 !important; margin-bottom:0 !important; }
.shp-cats { display:flex; justify-content:center; gap: 12px; flex-wrap: wrap; padding: 26px 0; }
.shp-cat { display:flex; flex-direction:column; align-items:center; gap:10px; width: 180px; padding: 8px 0; font-weight:700; font-size:15px; color: var(--shp-ink); text-decoration:none; }
.shp-caticon { width:64px; height:64px; border-radius:32px; background: var(--shp-sand); display:inline-flex; align-items:center; justify-content:center; color: var(--shp-ink); transition: background .15s, color .15s; }
.shp-caticon svg { width:30px; height:30px; }
.shp-cat:hover { color: var(--shp-accent); }
.shp-cat:hover .shp-caticon { background: var(--shp-tint); color: var(--shp-accent); }

/* karty */
.shp-cards { gap: 24px !important; margin-top: 28px; }
.shp-card { background:#fff; border:1px solid var(--shp-line); border-radius: 24px; padding: 28px !important; box-shadow: 0 6px 18px rgba(34,52,60,.05); }
.shp-card h3 { margin-bottom: 10px; }
.shp-account { font-size: 22px; color: var(--shp-ink) !important; margin-top: 2px !important; }
.shp-mail a { font-size: 20px; font-weight: 800; }

/* pás s výzvou */
.shp-band { background: var(--shp-tint); border-radius: 28px; padding: 48px 40px !important; }
.shp-band p { max-width: 640px; }

/* citát */
.shp-quote { font-family: var(--wp--preset--font-family--caveat) !important; color: var(--shp-accent) !important; font-size: 34px !important; font-weight: 600 !important; line-height: 1.15 !important; letter-spacing: 0 !important; margin: 28px 0 8px !important; }

/* FAQ */
.shp-faq { max-width: 820px; }
.shp-faq .wp-block-details { background:#fff; border:1px solid var(--shp-line); border-radius: 20px; padding: 18px 24px; margin: 0 0 12px !important; }
.shp-faq summary { font-weight: 800; color: var(--shp-ink); cursor: pointer; font-size: 17px; }
.shp-faq details p { margin-top: 10px; }

/* horní lišta */
.shp-topbar { background: var(--shp-accent); padding: 8px var(--wp--style--root--padding-right, 24px) !important; margin-top:0 !important; margin-bottom:0 !important; }
.shp-topbar .wp-block-group { align-items: center; }
.shp-claim { color:#fff !important; font-size: 13px; font-weight: 600; margin-top:0 !important; margin-bottom:0 !important; }
.shp-topbar .wp-block-social-links .wp-social-link { color:#fff !important; }
.shp-social { gap: 14px !important; }
.shp-social .wp-social-link svg { width: 18px; height: 18px; }
.shp-social-dark .wp-social-link { color: var(--shp-ink) !important; }
.shp-social-dark .wp-social-link:hover { color: var(--shp-accent) !important; }

/* hlavička */
.shp-header { background: #fff; border-bottom:1px solid var(--shp-line); padding: 14px var(--wp--style--root--padding-right, 24px) !important; margin-top:0 !important; margin-bottom:0 !important; position: sticky; top: 0; z-index: 50; }
.shp-header .wp-block-group { align-items:center; gap: 24px; }
.shp-header .wp-block-site-logo img { height: auto; }
.shp-nav { font-weight: 700; font-size: 15px; gap: 28px !important; }
.shp-nav a { color: var(--shp-ink); text-decoration: none; }
.shp-nav a:hover, .shp-nav .current-menu-item a { color: var(--shp-accent); }
.shp-minicart .wc-block-mini-cart__button { color: var(--shp-ink); }
.shp-minicart .wc-block-mini-cart__badge { background: var(--shp-accent) !important; color:#fff !important; border-color: var(--shp-accent) !important; }

/* patička */
.shp-footer { background: var(--shp-ink); color:#fff; padding: 48px var(--wp--style--root--padding-right, 24px) 24px !important; margin-top:0 !important; margin-bottom:0 !important; }
.shp-footer p, .shp-footer h4, .shp-footer li, .shp-footer a { color:#fff !important; }
.shp-footer h4 { font-size: 15px; margin-bottom: 12px; }
.shp-footer-logo img { height: 96px; width: auto; }
.shp-footer-claim { color: #fff !important; font-size: 28px !important; margin-top: 12px !important; }
.shp-footer-sub { opacity: .75; font-size: 14px; }
.shp-links { list-style:none; padding:0; margin:0 0 20px; }
.shp-links li { margin: 0 0 8px; font-size: 15px; }
.shp-links a { text-decoration:none; opacity:.85; }
.shp-links a:hover { opacity:1; text-decoration: underline; }
.shp-social-footer .wp-social-link { color:#fff !important; }
.shp-footer-bottom { border-top: 1px solid rgba(255,255,255,.15); margin-top: 32px !important; padding-top: 18px; }
.shp-copy { font-size: 13px; opacity: .6; }

/* WooCommerce: produktové karty */
.woocommerce ul.products li.product, .wc-block-grid__product, .wc-block-product { background:#fff; border:1px solid var(--shp-line); border-radius: 24px; overflow:hidden; padding: 0 0 18px !important; box-shadow: 0 6px 18px rgba(34,52,60,.05); transition: transform .2s, box-shadow .2s; text-align:left; }
.woocommerce ul.products li.product:hover { transform: translateY(-3px); box-shadow: 0 14px 32px rgba(34,52,60,.10); }
.woocommerce ul.products li.product a img { border-radius: 0; margin: 0 0 14px !important; background: var(--shp-sand); aspect-ratio: 1/1; object-fit: cover; }
.woocommerce ul.products li.product .woocommerce-loop-product__title { font-size: 16px !important; font-weight: 800; color: var(--shp-ink); padding: 0 18px !important; }
.woocommerce ul.products li.product .price { color: var(--shp-ink) !important; font-weight: 800; padding: 0 18px; font-size: 16px !important; }
.woocommerce ul.products li.product .button { margin: 10px 18px 0 !important; border-radius: 20px !important; background: var(--shp-accent) !important; color:#fff !important; font-weight: 800; }
.woocommerce span.onsale { background: var(--shp-accent); border-radius: 999px; }

@media (max-width: 900px) {
  .shp-section, .shp-hero, .shp-pagehead { padding-top: 48px !important; padding-bottom: 48px !important; }
  .shp-claim { display:none; }
  .shp-topbar .wp-block-group { justify-content: flex-end !important; }
  .shp-band { padding: 32px 24px !important; }
  .wp-block-columns { gap: 32px; }
  .shp-cat { width: 110px; font-size: 14px; }
}
